import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"Postman API Testing Toolkit","description":"A production-shaped Postman workspace: chained CRUD contract tests, HMAC request signing, data-driven runs, Newman CI with HTML reports.","frontmatter":{"title":"Postman API Testing Toolkit","description":"A production-shaped Postman workspace: chained CRUD contract tests, HMAC request signing, data-driven runs, Newman CI with HTML reports."},"headers":[],"relativePath":"en/projects/postman-api-testing-toolkit/index.md","filePath":"en/projects/postman-api-testing-toolkit/index.md"}`),a={name:`en/projects/postman-api-testing-toolkit/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="postman-api-testing-toolkit" tabindex="-1">Postman API Testing Toolkit <a class="header-anchor" href="#postman-api-testing-toolkit" aria-label="Permalink to “Postman API Testing Toolkit”">​</a></h1><p><strong><a href="https://github.com/Godde3s/postman-api-testing-toolkit" target="_blank" rel="noreferrer">Postman API Testing Toolkit</a></strong> answers a different kind of interview question: <em>how do you test an API?</em> Not with one GET and a status-code assert — with a layered testing architecture that answers three separate questions: does it work, does it match its contract, and does it fail gracefully?</p><h2 id="what-a-passing-collection-actually-proves" tabindex="-1">What a passing collection actually proves <a class="header-anchor" href="#what-a-passing-collection-actually-proves" aria-label="Permalink to “What a passing collection actually proves”">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Question</th><th>Technique</th></tr></thead><tbody><tr><td>Smoke</td><td>Is it up?</td><td>One request per critical route + response-time SLA</td></tr><tr><td>Contract</td><td>Shape correct?</td><td>Field-by-field assertions: type, presence, format</td></tr><tr><td>Functional</td><td>Behavior correct?</td><td>Chained CRUD: create → read → update → delete via collection variables</td></tr><tr><td>Negative</td><td>Errors sane?</td><td>404s, malformed payloads, boundary values</td></tr><tr><td>Data-driven</td><td>All inputs?</td><td>CSV-driven iterations through Newman</td></tr></tbody></table><h2 id="techniques-on-display" tabindex="-1">Techniques on display <a class="header-anchor" href="#techniques-on-display" aria-label="Permalink to “Techniques on display”">​</a></h2><ul><li><strong>HMAC request signing in the sandbox</strong> — a pre-request script computes <code>HMAC_SHA256(method + path + timestamp + bodyHash)</code> with CryptoJS, the pattern behind every serious API&#39;s anti-replay scheme.</li><li><strong>Dynamic payloads</strong> — <code>$randomUUID</code> and <code>pm.variables.replaceIn()</code> so every run produces unique, traceable data.</li><li><strong>CI as the canary</strong> — GitHub Actions runs both collections via Newman on every push <em>and</em> daily, so contract drift from public APIs gets caught even on weeks you commit nothing. HTML reports ship as artifacts.</li></ul><h2 id="why-a-collection-repo-belongs-next-to-real-services" tabindex="-1">Why a &quot;collection repo&quot; belongs next to real services <a class="header-anchor" href="#why-a-collection-repo-belongs-next-to-real-services" aria-label="Permalink to “Why a &quot;collection repo&quot; belongs next to real services”">​</a></h2><p>Because testing is where API engineering shows its discipline. The toolkit is designed to run against <a href="/Usf/en/projects/taskflow-api/">TaskFlow API</a> and public reference APIs, and its conventions — <code>module :: behavior</code> test naming, zero anonymous asserts, state never hardcoded — are the same ones I bring to team codebases.</p><div class="tip custom-block"><p class="custom-block-title">Try it</p><p>Import the collections into Postman, or run headless: <code>newman run collections/rest-crud-api.postman_collection.json -r htmlextra</code> — <a href="https://github.com/Godde3s/postman-api-testing-toolkit" target="_blank" rel="noreferrer">github.com/Godde3s/postman-api-testing-toolkit</a></p></div>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};